var seed=20240607;
function rnd(){seed|=0;seed=seed+0x6D2B79F5|0;var t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;}
var N=6,I=1,J=4;
var BLUE='#0B4FC0',RUST='#B4552F',INK='#04204B',SEC='#3D5F91',FAINT='#8098BC',GREY='#EEF1F6';
var F='12px sans-serif',FB='bold 12px sans-serif',F11='11px sans-serif';
var PER=18,B=[0,2,8,11,15.5,18];
var shade=[];
for(var a0=0;a0<N;a0++){shade.push([]);for(var b0=0;b0<N;b0++)shade[a0].push(0.02+0.08*rnd());}
var TITLES=['1 · pick a pair (i, j)','2 · outgoing: combine row i with row j','3 · gate and add','4 · incoming: columns instead of rows','5 · every pair at once'];
var CAPS=['pick one entry z_25 of the pair representation: residues i = 2 and j = 5',
'outgoing: edges leaving i and j, multiplied channel by channel and summed over every third residue k',
'z_ij <- z_ij + g_ij * Linear(LN(sum_k a_ik * b_jk))',
'incoming: edges arriving at i and j',
'done for all N^2 pairs: a matrix product per channel, N^3 work'];
function cl(x){return x<0?0:x>1?1:x;}
function e(x){x=cl(x);return x*x*(3-2*x);}
function wv(x){return x>0&&x<1?Math.sin(Math.PI*x):0;}
function part(pts,q){var ls=[],tot=0,i;for(i=1;i<pts.length;i++){var l=Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]);ls.push(l);tot+=l;}
 var rem=q*tot,out=[pts[0]];
 for(i=1;i<pts.length;i++){if(rem>=ls[i-1]){out.push(pts[i]);rem-=ls[i-1];}else{var f=rem/ls[i-1];out.push([pts[i-1][0]+(pts[i][0]-pts[i-1][0])*f,pts[i-1][1]+(pts[i][1]-pts[i-1][1])*f]);break;}}
 return out;}
return {draw:function(ctx,w,h,time,dt){
 ctx.globalAlpha=1;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,w,h);
 var t=time%PER,ph=0;
 while(ph<4&&t>=B[ph+1])ph++;
 function txt(s,x,y,col,al,font,align){ctx.globalAlpha=al;ctx.fillStyle=col;ctx.font=font;ctx.textAlign=align||'left';ctx.textBaseline='alphabetic';ctx.fillText(s,x,y);ctx.globalAlpha=1;}
 function box(x,y,ww,hh,col,al){ctx.globalAlpha=al;ctx.fillStyle=col;ctx.fillRect(x,y,ww,hh);ctx.globalAlpha=1;}
 function pk(x,y){box(x-6,y-6,12,6,BLUE,1);box(x-6,y,12,6,RUST,1);}
 function wrap(s,maxW){ctx.font=F;var words=s.split(' '),lines=[],cur='';for(var i=0;i<words.length;i++){var tr=cur?cur+' '+words[i]:words[i];if(ctx.measureText(tr).width>maxW&&cur){lines.push(cur);cur=words[i];}else cur=tr;}lines.push(cur);return lines;}
 // layout
 var wide=w>=620,gy=60,gx=wide?44:28;
 var gs=wide?Math.min(w*0.4,240):Math.min(150,w*0.42),cs=gs/N,capTop=h-56;
 var bh=14,boxH=34,bx,by,bw,boxX,boxY,boxW,rx,ax0,aw,ay,ah;
 if(wide){bx=gx;bw=gs*0.55;by=gy+gs+26;boxX=bx+bw+14;boxW=116;boxY=by+bh/2-boxH/2;rx=boxX+boxW+12;ax0=rx+16;aw=w-ax0-12;ay=gy-20;ah=capTop-ay-4;}
 else{bx=gx+gs+16;bw=w-bx-12;by=gy+34;boxX=bx;boxW=bw;boxY=by+bh+16;rx=gx+gs+8;ax0=8;aw=w-16;ay=gy+gs+14;ah=capTop-ay-2;}
 var R=Math.min((ah-56)/1.45,(aw/2-34)/0.9,190);if(R<30)R=30;
 var acx=ax0+aw/2,acy=ay+26+R*0.95+10,nr=wide?12:11;
 var P=[];
 for(var n=0;n<N;n++){var an=(-210+48*n)*Math.PI/180;P.push({x:acx+R*Math.cos(an),y:acy+R*Math.sin(an)});}
 // state
 var pairA=0,hl=0,mode=0,s=0,barS=0,vis=0,u=0;
 if(ph==0)pairA=e((t-0.3)/0.8);else if(ph<4)pairA=1;else pairA=1-e((t-15.7)/0.6);
 if(ph==1){mode=0;vis=1-e((t-7.5)/0.5);hl=e((t-2)/0.6)*vis;s=cl((t-2.7)/4.6)*6;barS=s;}
 if(ph==2){u=(t-8)/3;barS=6*(1-e(u/0.3));}
 if(ph==3){mode=1;vis=1-e((t-14.9)/0.5);hl=e((t-11)/0.6)*vis;s=cl((t-11.6)/3.3)*6;barS=s*(1-e((t-15)/0.5));}
 var kc=-1,fr=0;
 if((ph==1||ph==3)&&s>0&&s<6){kc=Math.floor(s);fr=s-kc;}
 var fl=Math.sin(Math.PI*fr);
 function bump(sum){return ph==4?wv((t-15.6)*0.9-sum/10*0.9):0;}
 // captions
 var la=Math.min(e((t-B[ph])/0.4),1-e((t-(B[ph+1]-0.4))/0.4));
 txt(TITLES[ph],w/2,22,INK,la,'bold 13px sans-serif','center');
 var lines=wrap(CAPS[ph],w-24);
 for(var li=0;li<lines.length;li++)txt(lines[li],w/2,capTop+14+li*15,SEC,la,F,'center');
 // grid
 txt('z: rows i, columns j',gx,gy-24,SEC,1,F11,'left');
 function lab(idx,isRow,x,y,al){
  var col=INK,f=F11;
  if(hl>0.3&&(isRow==(mode==0))){if(idx==I){col=BLUE;f=FB;}else if(idx==J){col=RUST;f=FB;}}
  else if(kc==idx&&hl>0.3){f=FB;}
  txt(''+(idx+1),x,y,col,1,f,al);
 }
 for(var q=0;q<N;q++){lab(q,false,gx+(q+0.5)*cs,gy-8,'center');lab(q,true,gx-7,gy+(q+0.5)*cs+4,'right');}
 var r,c;
 for(r=0;r<N;r++)for(c=0;c<N;c++){
  var x=gx+c*cs+1,y=gy+r*cs+1,sz=cs-2;
  box(x,y,sz,sz,GREY,1);box(x,y,sz,sz,INK,shade[r][c]);
  var line=mode==0?r:c,oth=mode==0?c:r;
  if(hl>0){if(line==I)box(x,y,sz,sz,BLUE,0.22*hl);if(line==J)box(x,y,sz,sz,RUST,0.22*hl);}
  if(kc>=0&&oth==kc){if(line==I)box(x,y,sz,sz,BLUE,0.8*fl);if(line==J)box(x,y,sz,sz,RUST,0.8*fl);}
  var bp=bump(r+c);if(bp>0)box(x,y,sz,sz,BLUE,0.7*bp);
  if(r==I&&c==J)box(x,y,sz,sz,INK,pairA);
 }
 if(hl>0){
  ctx.lineWidth=2;ctx.globalAlpha=hl;
  ctx.strokeStyle=BLUE;if(mode==0)ctx.strokeRect(gx,gy+I*cs,gs,cs);else ctx.strokeRect(gx+I*cs,gy,cs,gs);
  ctx.strokeStyle=RUST;if(mode==0)ctx.strokeRect(gx,gy+J*cs,gs,cs);else ctx.strokeRect(gx+J*cs,gy,cs,gs);
  ctx.globalAlpha=1;
 }
 var pu=ph==2?wv((u-0.8)/0.2):0;
 if(pu>0){var cx0=gx+J*cs,cy0=gy+I*cs;box(cx0+1,cy0+1,cs-2,cs-2,BLUE,0.5*pu);ctx.globalAlpha=pu;ctx.strokeStyle=BLUE;ctx.lineWidth=2.5;ctx.strokeRect(cx0-pu*5,cy0-pu*5,cs+pu*10,cs+pu*10);ctx.globalAlpha=1;}
 // residues
 ctx.strokeStyle=FAINT;ctx.lineWidth=1;ctx.globalAlpha=0.6;ctx.beginPath();ctx.arc(acx,acy,R,-210*Math.PI/180,30*Math.PI/180);ctx.stroke();ctx.globalAlpha=1;
 function edge(a,b,col,al,g,bend,lw,arrow){
  if(g<=0.01||al<=0.005)return;
  ctx.globalAlpha=al;ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=lw;
  var pa=P[a],pb=P[b];
  if(a==b){var dx0=(pa.x-acx)/R,dy0=(pa.y-acy)/R;ctx.beginPath();ctx.arc(pa.x+dx0*(nr+7),pa.y+dy0*(nr+7),8,0,2*Math.PI*g);ctx.stroke();ctx.globalAlpha=1;return;}
  var dx=pb.x-pa.x,dy=pb.y-pa.y,L=Math.sqrt(dx*dx+dy*dy),ux=dx/L,uy=dy/L;
  var sx=pa.x+ux*nr,sy=pa.y+uy*nr,ex=pb.x-ux*(nr+3),ey=pb.y-uy*(nr+3);
  var qx=(sx+ex)/2-uy*bend*L,qy=(sy+ey)/2+ux*bend*L;
  var qf=function(v){var m=1-v;return [m*m*sx+2*m*v*qx+v*v*ex,m*m*sy+2*m*v*qy+v*v*ey];};
  var p=qf(0);ctx.beginPath();ctx.moveTo(p[0],p[1]);
  for(var i=1;i<=14;i++){p=qf(g*i/14);ctx.lineTo(p[0],p[1]);}
  ctx.stroke();
  if(arrow&&g>0.9){var p2=qf(g-0.04),ag=Math.atan2(p[1]-p2[1],p[0]-p2[0]);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(p[0]-8*Math.cos(ag-0.4),p[1]-8*Math.sin(ag-0.4));ctx.lineTo(p[0]-8*Math.cos(ag+0.4),p[1]-8*Math.sin(ag+0.4));ctx.closePath();ctx.fill();}
  ctx.globalAlpha=1;
 }
 // wave edges
 if(ph==4){for(var a=0;a<N;a++)for(var b=a+1;b<N;b++){edge(a,b,BLUE,0.1+0.6*bump(a+b),1,0,1.5,false);}}
 // triangle + sweep edges
 if(ph==1||ph==3){
  var nDone=s>=6?6:(kc>=0?kc:0);
  for(var k=0;k<=Math.min(5,kc>=0?kc:nDone-1);k++){
   var cur=(k==kc),g=cur?e(fr*2.5):1,al=cur?1:0.13*vis;
   var bd=(k==I||k==J)?0.28:0;
   if(cur&&k!=I&&k!=J){ctx.globalAlpha=0.07*g;ctx.fillStyle=INK;ctx.beginPath();ctx.moveTo(P[I].x,P[I].y);ctx.lineTo(P[J].x,P[J].y);ctx.lineTo(P[k].x,P[k].y);ctx.closePath();ctx.fill();ctx.globalAlpha=1;}
   if(mode==0){edge(I,k,BLUE,al,g,bd,2.2,true);edge(J,k,RUST,al,g,bd,2.2,true);}
   else{edge(k,I,BLUE,al,g,bd,2.2,true);edge(k,J,RUST,al,g,bd,2.2,true);}
  }
 }
 edge(I,J,INK,pairA,e(pairA*1.2),0,2.6,false);
 // nodes
 for(var m=0;m<N;m++){
  var pp=P[m];
  ctx.beginPath();ctx.arc(pp.x,pp.y,nr,0,2*Math.PI);ctx.fillStyle='#ffffff';ctx.fill();
  if(hl>0&&(m==I||m==J)){ctx.globalAlpha=0.25*hl;ctx.fillStyle=m==I?BLUE:RUST;ctx.beginPath();ctx.arc(pp.x,pp.y,nr,0,2*Math.PI);ctx.fill();ctx.globalAlpha=1;}
  var wb=bump(m*2+2.5);
  ctx.beginPath();ctx.arc(pp.x,pp.y,nr,0,2*Math.PI);
  if(m==kc&&la>0){ctx.strokeStyle=INK;ctx.lineWidth=3;}
  else if((m==I||m==J)&&pairA>0.05){ctx.strokeStyle=INK;ctx.lineWidth=1.2+1.8*pairA;}
  else{ctx.strokeStyle=wb>0?BLUE:INK;ctx.lineWidth=1.2+wb*2;}
  ctx.stroke();
  txt(''+(m+1),pp.x,pp.y+4,INK,1,F,'center');
  var nl='';
  if(m==I&&pairA>0.3)nl=(m==kc)?'i = k':'i';
  else if(m==J&&pairA>0.3)nl=(m==kc)?'j = k':'j';
  else if(m==kc)nl='k';
  if(nl){var ox=(pp.x-acx)/R,oy=(pp.y-acy)/R;var lc=(hl>0.3&&m==I)?BLUE:(hl>0.3&&m==J)?RUST:INK;txt(nl,pp.x+ox*(nr+14),pp.y+oy*(nr+14)+4,lc,1,FB,'center');}
 }
 // status
 var st='';
 if(ph==0)st='pair (i, j) = (2, 5)';
 else if(ph==1||ph==3){st=kc>=0?'k = '+(kc+1)+' of 6':(s>=6?'sum over all k complete':(mode==0?'row i with row j':'column i with column j'));}
 else if(ph==2)st=u<0.3?'sum leaves the bar':(u<0.55?'LayerNorm, Linear, gate':'update flows into z_ij');
 else st='36 pairs x 6 values of k = 216 products';
 txt(st,acx,ay+10,SEC,1,F,'center');
 // accumulation bar
 var lt=(ph==3)?'sum over k of a_ki * b_kj':'sum over k of a_ik * b_jk';
 if(wide)txt(lt,bx,by-6,INK,1,F11,'left');
 else{var sp=(ph==3)?['sum over k of','a_ki * b_kj']:['sum over k of','a_ik * b_jk'];txt(sp[0],bx,gy+10,INK,1,F11,'left');txt(sp[1],bx,gy+24,INK,1,F11,'left');}
 box(bx,by,bw,bh,GREY,1);
 var sw=bw/6;
 for(var sg=0;sg<6;sg++){var am=cl(barS-sg);if(am>0){var segw=sw*e(am*1.5);var wd=Math.max(0,segw-1);box(bx+sg*sw,by,wd,bh/2,BLUE,0.85);box(bx+sg*sw,by+bh/2,wd,bh/2,RUST,0.85);}}
 ctx.strokeStyle=INK;ctx.lineWidth=1;ctx.strokeRect(bx,by,bw,bh);
 // gate box
 var gl=ph==2?wv((u-0.3)/0.25):0;
 box(boxX,boxY,boxW,boxH,'#ffffff',1);box(boxX,boxY,boxW,boxH,BLUE,0.12*gl);
 ctx.strokeStyle=gl>0?BLUE:INK;ctx.lineWidth=1.2+2*gl;ctx.strokeRect(boxX,boxY,boxW,boxH);
 txt('LayerNorm, Linear,',boxX+boxW/2,boxY+14,INK,1,F11,'center');
 txt('x gate g_ij',boxX+boxW/2,boxY+27,INK,1,F11,'center');
 // packets in phase 3
 if(ph==2){
  var s1x=wide?bx+bw:bx+bw/2,s1y=wide?by+bh/2:by+bh;
  var e1x=wide?boxX:boxX+boxW/2,e1y=wide?by+bh/2:boxY;
  var q1=e((u-0.05)/0.3);
  if(q1>0&&q1<1)pk(s1x+(e1x-s1x)*q1,s1y+(e1y-s1y)*q1);
  var ox2=wide?boxX+boxW:boxX,oy2=boxY+boxH/2;
  var cyc=gy+(I+0.5)*cs,cxc=gx+(J+0.5)*cs;
  var path=[[ox2,oy2],[rx,oy2],[rx,cyc],[cxc,cyc]];
  var q2=e((u-0.55)/0.3);
  if(q2>0){
   var pts=part(path,q2),ta=1-cl((u-0.85)/0.1);
   ctx.globalAlpha=0.5*ta;ctx.strokeStyle=BLUE;ctx.lineWidth=2.5;ctx.beginPath();ctx.moveTo(pts[0][0],pts[0][1]);
   for(var pi=1;pi<pts.length;pi++)ctx.lineTo(pts[pi][0],pts[pi][1]);ctx.stroke();ctx.globalAlpha=1;
   if(q2<1){var lp=pts[pts.length-1];pk(lp[0],lp[1]);}
  }
 }
}};
